\title{Quantitative Bracketing, an Explicit Series Representation,\\
and the Exact $\Theta(1/n)$ Convergence Order\\
of the Euler--Mascheroni Constant}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
The Euler--Mascheroni constant $\gamma = \lim_{n\to\infty}(H_n - \ln n)$ is
classically squeezed between two monotone sequences,
$a_n = H_n - \ln(n+1) < \gamma < H_n - \ln n = b_n$, but the standard
development records only crude numerical enclosures such as
$\tfrac12 < \gamma < \tfrac23$. We make this bracketing \emph{quantitative}.
We prove that the width of the bracketing interval is, exactly, a single
logarithm, $b_n - a_n = \ln\bigl(\tfrac{n+1}{n}\bigr)$, and we sandwich it
two-sidedly by elementary convexity,
$\tfrac{1}{n+1} \le \ln\bigl(\tfrac{n+1}{n}\bigr) \le \tfrac{1}{n}$ for
$n \ge 1$. Consequently the convergence order of the defining sequence is
\emph{exactly linear}, $\Theta(1/n)$: the lower approximant undershoots and
the upper approximant overshoots $\gamma$ each by strictly less than $1/n$.
We further establish the classical identity exhibiting $\gamma$ as the sum of
an explicit nonnegative convergent series,
$\gamma = \sum_{k\ge 0}\bigl(\tfrac{1}{k+1} - \ln\tfrac{k+2}{k+1}\bigr)$,
whose partial sums coincide \emph{exactly} with $a_n$, and we identify the
series tail $\sum_{k\ge n} t_k$ with the approximation error $\gamma - a_n$,
hence also bounded by $1/n$. The two-sided width bound is the precise
structural obstruction motivating series accelerations and explains why
elementary truncations of this series are ``irrationality-blind.'' All results
have been formally verified in the Lean~4 proof assistant on top of Mathlib's
\texttt{Real.eulerMascheroniConstant}.
\end{abstract}

\section{Introduction}

\subsection{The constant}
The harmonic numbers $H_n = \sum_{k=1}^{n} \tfrac{1}{k}$ diverge logarithmically.
Euler observed that the difference $H_n - \ln n$ converges, and named the limit
\[
  \gamma = \lim_{n\to\infty}\bigl(H_n - \ln n\bigr) = 0.57721566490153286\ldots
\]
The constant $\gamma$ appears throughout analysis and number theory: in the
Laurent expansion of the Riemann zeta function at $s=1$, in Mertens' third
theorem, in the digamma value $\psi(1) = -\gamma$, and in the analysis of
randomized algorithms. Whether $\gamma$ is rational or irrational remains open;
if rational, its denominator must exceed $10^{242080}$.

\subsection{Known facts and the gap we fill}
Mathlib defines $\gamma$ as \texttt{Real.eulerMascheroniConstant}, the limit of
the increasing sequence $a_n := H_n - \ln(n+1)$, and proves that the companion
sequence $b_n := H_n - \ln n$ ($n \ge 1$) is decreasing with the same limit,
yielding the strict bracket
\begin{equation}
  a_n < \gamma < b_n \qquad (n \ge 1). \label{eq:bracket}
\end{equation}
However, the library only extracts $\tfrac12 < \gamma < \tfrac23$ and records no
information about the \emph{rate} at which \eqref{eq:bracket} tightens. This
paper supplies that missing quantitative layer.

\subsection{Contributions}
\begin{enumerate}
  \item \textbf{Closed-form width} (\texttt{bracket\_width}):
        $b_n - a_n = \ln\tfrac{n+1}{n}$.
  \item \textbf{Two-sided width bound} (\texttt{width\_le}, \texttt{width\_ge},
        \texttt{bracket\_width\_order}):
        $\tfrac{1}{n+1} \le \ln\tfrac{n+1}{n} \le \tfrac1n$.
  \item \textbf{Quantitative convergence} (\texttt{gamma\_sub\_seq\_lt},
        \texttt{seq'\_sub\_gamma\_lt}): $\gamma - a_n < \tfrac1n$ and
        $b_n - \gamma < \tfrac1n$.
  \item \textbf{Series representation}
        (\texttt{tsum\_eulerMascheroni}): $\gamma = \sum_{k\ge 0} t_k$ with
        $t_k \ge 0$ and partial sums equal to $a_n$.
  \item \textbf{Tail--error identity} (\texttt{tail\_eq\_error},
        \texttt{tsum\_tail\_lt}):
        $\sum_{k\ge n} t_k = \gamma - a_n < \tfrac1n$.
\end{enumerate}

\section{Definitions and notation}
Throughout, $\ln$ is the natural logarithm and $H_n = \sum_{k=1}^{n} 1/k$ the
$n$-th harmonic number ($H_0 = 0$).

\begin{definition}[Lower approximant]
For $n \in \NN$, $a_n := H_n - \ln(n+1)$ (Mathlib's
\texttt{Real.eulerMascheroniSeq}). It is strictly increasing, $a_0 = 0$.
\end{definition}

\begin{definition}[Upper approximant]
For $n \ge 1$, $b_n := H_n - \ln n$ (Mathlib's
\texttt{Real.eulerMascheroniSeq'}, with a junk value at $n=0$). It is strictly
decreasing for $n \ge 1$, $b_1 = 1$.
\end{definition}

\begin{definition}[Euler--Mascheroni constant]
$\gamma := \lim_{n\to\infty} a_n = \texttt{Real.eulerMascheroniConstant}$.
Mathlib proves $a_n \to \gamma$, $b_n \to \gamma$, and \eqref{eq:bracket}.
\end{definition}

\begin{definition}[Series term]
For $k \in \NN$,
\[
  t_k := \frac{1}{k+1} - \ln\!\left(\frac{k+2}{k+1}\right)
       = \frac{1}{k+1} - \ln\!\left(1 + \frac{1}{k+1}\right)
\]
(Mathlib's \texttt{EulerMascheroniSeries.term}).
\end{definition}

\begin{lemma}[Fundamental log inequality]\label{lem:log}
For every $x > 0$, $\ln x \le x - 1$, with equality iff $x = 1$. (Mathlib:
\texttt{Real.log\_le\_sub\_one\_of\_pos}.)
\end{lemma}
\begin{proof}
$f(x) = x - 1 - \ln x$ has $f'(x) = 1 - 1/x$, negative on $(0,1)$ and positive
on $(1,\infty)$, so $f$ attains its global minimum $f(1) = 0$.
\end{proof}

\section{The bracket width in closed form}
\begin{theorem}[Closed-form bracket width]\label{thm:width}
For all $n \ge 1$, $\; b_n - a_n = \ln\bigl(\tfrac{n+1}{n}\bigr)$.
\end{theorem}
\begin{proof}
$b_n - a_n = (H_n - \ln n) - (H_n - \ln(n+1)) = \ln(n+1) - \ln n
 = \ln\tfrac{n+1}{n}$, the harmonic terms cancelling identically.
\end{proof}

\section{Two-sided estimate of the width}
\begin{theorem}[Upper bound]\label{thm:upper}
For all $n \ge 1$, $\; \ln\bigl(\tfrac{n+1}{n}\bigr) \le \tfrac{1}{n}$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:log} at $x = \tfrac{n+1}{n}$, where
$x - 1 = \tfrac{1}{n}$.
\end{proof}

\begin{theorem}[Lower bound]\label{thm:lower}
For all $n \ge 1$, $\; \tfrac{1}{n+1} \le \ln\bigl(\tfrac{n+1}{n}\bigr)$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:log} at $x = \tfrac{n}{n+1}$, where
$x - 1 = -\tfrac{1}{n+1}$, giving $\ln\tfrac{n}{n+1} \le -\tfrac{1}{n+1}$.
Since $\ln\tfrac{n}{n+1} = -\ln\tfrac{n+1}{n}$, the claim follows.
\end{proof}

\begin{theorem}[Exact linear order]\label{thm:order}
For all $n \ge 1$, $\; \tfrac{1}{n+1} \le b_n - a_n \le \tfrac{1}{n}$; in
particular $b_n - a_n = \Theta(1/n)$.
\end{theorem}
The lower bound is load-bearing: it certifies the sequence cannot converge
faster than linearly, the precise obstruction that accelerated schemes
circumvent.

\section{Quantitative convergence to $\gamma$}
\begin{theorem}[Lower approximant error]\label{thm:errlow}
For all $n \ge 1$, $\; \gamma - a_n < \tfrac{1}{n}$.
\end{theorem}
\begin{proof}
By \eqref{eq:bracket}, $\gamma < b_n$, so
$\gamma - a_n < b_n - a_n = \ln\tfrac{n+1}{n} \le \tfrac1n$ by
Theorems~\ref{thm:width},~\ref{thm:upper}.
\end{proof}

\begin{theorem}[Upper approximant error]\label{thm:errup}
For all $n \ge 1$, $\; b_n - \gamma < \tfrac{1}{n}$.
\end{theorem}
\begin{proof}
By \eqref{eq:bracket}, $a_n < \gamma$, so
$b_n - \gamma < b_n - a_n \le \tfrac1n$.
\end{proof}

\noindent\emph{Numerical illustration.} Ten correct digits require
$n \approx 10^{10}$; a hundred digits require $n \approx 10^{100}$.

\section{An explicit convergent series for $\gamma$}
\begin{lemma}[Nonnegativity]\label{lem:nonneg}
For all $k$, $t_k \ge 0$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:log} at $x = \tfrac{k+2}{k+1}$,
$\ln\tfrac{k+2}{k+1} \le \tfrac{1}{k+1}$, so $t_k \ge 0$.
\end{proof}

\begin{lemma}[Telescoping partial sums]\label{lem:partial}
For all $n$, $\; \sum_{k=0}^{n-1} t_k = a_n = H_n - \ln(n+1)$.
\end{lemma}
\begin{proof}
$\sum_{k=0}^{n-1} \tfrac{1}{k+1} = H_n$, and
$\sum_{k=0}^{n-1}\ln\tfrac{k+2}{k+1}
 = \ln\prod_{k=0}^{n-1}\tfrac{k+2}{k+1} = \ln(n+1)$ by telescoping.
\end{proof}

\begin{theorem}[Series representation]\label{thm:series}
The series $\sum_{k\ge 0} t_k$ converges and
\[
  \gamma = \sum_{k=0}^{\infty}\left(\frac{1}{k+1} - \ln\frac{k+2}{k+1}\right)
         = \sum_{m=1}^{\infty}\left(\frac{1}{m} - \ln\Bigl(1+\frac{1}{m}\Bigr)\right),
\]
in the strong sense \texttt{HasSum}.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:partial} the partial sums equal $a_n \to \gamma$. For
nonnegative terms (Lemma~\ref{lem:nonneg}), convergence of the $\NN$-indexed
partial sums is equivalent to \texttt{HasSum}
(\texttt{hasSum\_iff\_tendsto\_nat\_of\_nonneg}).
\end{proof}

\begin{remark}
Nonnegativity is essential: for a general real series, \texttt{HasSum} is
strictly stronger than convergence of the $\NN$-ordered partial sums.
\end{remark}

\section{The tail equals the approximation error}
\begin{theorem}[Tail--error identity]\label{thm:tail}
For all $n$, $\; \sum_{k=0}^{\infty} t_{k+n} = \gamma - a_n$.
\end{theorem}
\begin{proof}
By summability, split off the first $n$ terms:
$\gamma = \sum_{k=0}^{n-1} t_k + \sum_{k=0}^{\infty} t_{k+n}
       = a_n + \sum_{k=0}^{\infty} t_{k+n}$, using Lemma~\ref{lem:partial}.
\end{proof}

\begin{theorem}[Tail bound]\label{thm:tailbound}
For all $n \ge 1$, $\; \sum_{k=0}^{\infty} t_{k+n} < \tfrac{1}{n}$.
\end{theorem}
\begin{proof}
Immediate from Theorems~\ref{thm:tail} and~\ref{thm:errlow}.
\end{proof}

\section{Algorithms}
\subsection{Certified rational enclosure}
\begin{verbatim}
ENCLOSE(target_width w):
  n <- ceil(1 / w)
  H <- 0; for k in 1..n: H <- H + 1/k
  a <- H - ln(n + 1)      # a_n < gamma
  b <- H - ln(n)          # gamma < b_n,  b - a = ln((n+1)/n) <= 1/n
  return (a, b)
\end{verbatim}
Complexity: $O(n)$ for additive precision $\sim 1/n$; $d$ digits cost
$\Theta(10^d)$ work.

\subsection{Series summation with rigorous tail control}
\begin{verbatim}
SERIES_SUM(N):
  S <- 0
  for k in 0..N-1:
     t <- 1/(k+1) - ln((k+2)/(k+1))    # t_k >= 0
     S <- S + t                         # S = a_N
  return S, 1/N        # 0 < gamma - S < 1/N
\end{verbatim}

\section{Applications and discussion}
\textbf{Why accelerations exist.} Theorem~\ref{thm:order} is a hard lower bound
on the convergence rate, quantifying the folklore that $H_n - \ln n$ converges
too slowly to be useful beyond a few digits.

\noindent\textbf{Irrationality blindness.} Theorem~\ref{thm:tail} shows the
tail is $\gamma - a_n = \Theta(1/n)$, so no truncation of this series supplies
approximations sharp enough to force irrationality.

\noindent\textbf{Diagnostic for re-centering.} The lower bound
(Theorem~\ref{thm:lower}) certifies the presence of a leading $1/(2n)$ term in
the Euler--Maclaurin expansion, motivating the midpoint-recentering conjecture.

\section{Future directions}
\begin{conjecture}[Quadratic acceleration]
$b_n^{\mathrm{mid}} = H_n - \ln(n + \tfrac12)$ satisfies
$|\gamma - b_n^{\mathrm{mid}}| = O(1/n^2)$. Re-centering at the midpoint cancels
the leading $1/(2n)$ Euler--Maclaurin term certified by Theorem~\ref{thm:lower}.
\end{conjecture}
\begin{conjecture}[Sharp rational enclosure]
$0.5772 < \gamma < 0.5773$ is provable by evaluating $a_n, b_n$ at moderate $n$
with certified rational bounds on $\ln$; Theorem~\ref{thm:errlow} reduces this
to $O(1)$ digits of $\ln$-precision.
\end{conjecture}
\begin{conjecture}[Tail-based obstruction]
$R_n = \sum_{k\ge n} t_k$ satisfies $R_n > \tfrac{1}{2(n+1)}$, so
$R_n = \Theta(1/n)$ two-sided; the dual of Theorem~\ref{thm:lower} complements
the proven $R_n < 1/n$.
\end{conjecture}
\begin{conjecture}[Stieltjes generalization]
For each $m \ge 0$, $\gamma_m$ equals an explicit telescoping series
generalizing the $m=0$ identity; the telescoping of $\ln$ against $1/k$ should
extend to weight $(\ln k)^m$.
\end{conjecture}

\section{Conclusion}
The bracket width is exactly $\ln\tfrac{n+1}{n}$, squeezed between
$\tfrac{1}{n+1}$ and $\tfrac1n$, so the defining sequence converges at exact
order $\Theta(1/n)$. The same logarithm governs an explicit nonnegative series
for $\gamma$ whose tail \emph{is} the approximation error. These results explain
rigorously why the elementary approach is both beautiful and fundamentally
limited. All statements are formally verified in Lean~4 / Mathlib.

